 void Start(){folder=LWS.TruckSports.SportsEvidencePaths.Folder("WallballSmoke");Directory.CreateDirectory(folder);had=LWS.TruckSports.SportsPrefs.HasKey(WallballMatch.SetupKey);saved=LWS.TruckSports.SportsPrefs.GetString(WallballMatch.SetupKey);records.Add("Native gamepads before software injection="+Gamepad.all.Count);original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Wallball software keyboard");Application.logMessageReceived+=Log;memory=GC.GetTotalMemory(false);gc=GC.CollectionCount(0);steps.Push(Run());}
