 void Update(){if(finished)return;if(m!=null&&m.rules.Active&&!m.MenuOpen)samples.Add(Time.unscaledDeltaTime);try{while(steps.Count>0){var step=steps.Peek();if(!step.MoveNext()){steps.Pop();continue;}if(step.Current is IEnumerator nested){steps.Push(nested);continue;}return;}Finish(failed?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError("WB_SMOKE_FAIL "+e);Finish(2);}}
